msg.topic = "fan_status";
return msg;

var payload = msg.payload;
var topic = msg.topic || '';

// ===== =====
// We only IGNORE test messages, BUT we accept real ones MQTT
var currentTestMode = flow.get("testMode") || false;

// Check if a message is text
var isTestMessage = (msg._test === true ||
    msg._direct_injection === true ||
    msg._reset === true ||
    msg._scenario === true ||
    msg._test_scenario !== undefined ||
    msg._test_type !== undefined ||
    msg._test_name !== undefined);

// Если тестовый режим ВКЛЮЧЕН, НО это НЕ тестовое сообщение - ПРОПУСКАЕМ
if (currentTestMode === true && !isTestMessage) {
    node.log("⚠️ Test mode is ON, ignoring real MQTT data from: " + topic);
    return null;
}

// Если тестовый режим ВЫКЛЮЧЕН, ВСЕГДА обрабатываем
// Если тестовый режим ВКЛЮЧЕН, но это тестовое сообщение - обрабатываем
node.log("✅ Processing data from: " + topic + " (test mode: " + currentTestMode + ")");


// Если payload уже объект (JSON), обрабатываем его
if (typeof payload === 'object' && payload !== null) {
    node.log('Received JSON object: ' + JSON.stringify(payload).substring(0, 100));

    // Adafruit IO обычно отправляет: {"value": 22.5, "created_at": "...", "feed_id": ...}
    if (payload.value !== undefined) {
        msg.payload = {
            value: payload.value,
            last_value: payload.value,
            key: extractFeedName(topic),
            is_numeric: typeof payload.value === 'number',
            format: 'json_object'
        };
        return msg;
    }

    // Если есть feed_id или другие поля
    msg.payload = payload;
    return msg;
}

// Логи для отладки
node.log('Input topic: ' + topic + ', type: ' + typeof payload + ', value: ' + payload);

// 0. Обработка JSON объектов (самое важное!)
if (typeof payload === 'object' && payload !== null) {
    node.log('Detected JSON object, keys: ' + Object.keys(payload).join(', '));

    // Adafruit IO JSON формат обычно: {"value": 19.2, "created_at": "...", "feed_id": ...}
    if (payload.value !== undefined) {
        msg.payload = {
            value: payload.value,
            last_value: payload.value,
            key: extractFeedName(topic),
            is_numeric: typeof payload.value === 'number',
            format: 'json_object',
            raw_json: payload
        };
        node.log('Parsed JSON value: ' + payload.value);
        return msg;
    }

    // Если есть другие поля
    msg.payload = payload;
    return msg;
}

// 1. Обработка CSV формата ("181,,,")
if (typeof payload === 'string' && payload.includes(',')) {
    var csvParts = payload.split(',');

    // Фильтруем пустые значения
    var cleanParts = csvParts.filter(function(val) {
        return val !== '' && val !== null && val !== undefined;
    });

    // Если осталось только одно значение (например "181" из "181,,,")
    if (cleanParts.length === 1) {
        var val = cleanParts[0].trim();
        var num = parseFloat(val);
        var isNum = !isNaN(num);

        msg.payload = {
            value: isNum ? num : val,
            last_value: isNum ? num : val,
            key: extractFeedName(topic),
            format: 'csv_single',
            original_csv: payload
        };
        node.log('Parsed CSV single value: ' + val);
        return msg;
    }

    // Если несколько значений в CSV
    msg.payload = {
        csv_values: cleanParts,
        original_csv: payload,
        key: extractFeedName(topic),
        format: 'csv_multi',
        // Первое значение как основное
        value: cleanParts.length > 0 ? cleanParts[0] : null
    };
    node.log('Parsed CSV with ' + cleanParts.length + ' values');
    return msg;
}

// 2. Обычная строка ("181")
if (typeof payload === 'string') {
    payload = payload.trim();

    // Пустая строка
    if (payload === '') {
        msg.payload = { value: null, last_value: null, key: extractFeedName(topic) };
        return msg;
    }

    // Пытаемся распарсить JSON
    if (payload.startsWith('{') || payload.startsWith('[')) {
        try {
            msg.payload = JSON.parse(payload);
            node.log('Parsed JSON successfully');
            return msg;
        } catch(e) {
            // Ошибка парсинга JSON, обрабатываем как строку
            node.warn('JSON parse failed: ' + e.message);
        }
    }

    // Простое строковое значение
    var num = parseFloat(payload);
    var isNum = !isNaN(num) && payload !== '';

    msg.payload = {
        value: isNum ? num : payload,
        last_value: isNum ? num : payload,
        key: extractFeedName(topic),
        is_numeric: isNum,
        original_string: payload
    };
    node.log('Parsed as string: ' + payload + (isNum ? ' (number)' : ' (text)'));
    return msg;
}

// 3. Число
if (typeof payload === 'number') {
    msg.payload = {
        value: payload,
        last_value: payload,
        key: extractFeedName(topic),
        is_numeric: true
    };
    return msg;
}

// 4. Уже объект
if (typeof payload === 'object' && payload !== null) {
    // Добавляем key если нет
    if (!payload.key && payload.key !== '') {
        payload.key = extractFeedName(topic);
    }
    msg.payload = payload;
    return msg;
}

// 5. Другие типы
msg.payload = {
    value: payload,
    last_value: payload,
    key: extractFeedName(topic),
    raw_type: typeof payload
};
return msg;

// Функция извлечения имени фида
function extractFeedName(topic) {
    if (!topic || typeof topic !== 'string') return 'unknown';

    var parts = topic.split('/');
    var lastPart = parts[parts.length - 1];

    // Убираем суффиксы
    if (lastPart.endsWith('/json')) {
        lastPart = lastPart.replace('/json', '');
    }

    if (lastPart.endsWith('/csv')) {
        lastPart = lastPart.replace('/csv', '');
        return 'csv_multi_sensor';
    }

    // ИСПРАВЛЕННЫЙ маппинг на основе ваших данных
    var feedMapping = {
        "3278187": "temperature",  // Температура
        "3278188": "humidity",     // Влажность  
        "3278189": "gas",          // Газ
        "3278190": "motion",       // Движение
        "3278191": "fan",          // Вентилятор
        "temperature": "temperature",
        "humidity": "humidity",
        "gas": "gas",
        "motion": "motion",
        "fan": "fan"
    };

    return feedMapping[lastPart] || lastPart;
}

// Simplified mormalising for all formats
var data = msg.payload;
var originalTopic = msg.topic;

node.log('Normalize input: topic=' + originalTopic + ', data type: ' + typeof data + ', value: ' + data);

// Helper function for retrieving sensor type
function extractSensorType(topic) {
    if (!topic) return 'unknown';

    var parts = topic.split('/');
    var feedId = parts[parts.length - 1];

    // Убираем суффиксы /json и /csv
    if (feedId.endsWith('/json')) feedId = feedId.replace('/json', '');
    if (feedId.endsWith('/csv')) feedId = feedId.replace('/csv', '');

    // Маппинг ID на имена
    var mapping = {
        "3278187": "temperature",
        "3278188": "humidity",
        "3278189": "gas",
        "3278190": "motion",
        "3278191": "fan",
        "temperature": "temperature",
        "humidity": "humidity",
        "gas": "gas",
        "motion": "motion",
        "fan": "fan"
    };

    return mapping[feedId] || feedId;
}

// 1. Обработка объектов от парсера (JSON или обработанные данные)
if (data && typeof data === 'object') {
    // Если это объект с полем value (обработанный JSON)
    if (data.value !== undefined) {
        msg.payload = data.value;

        // Определяем тип сенсора
        var sensorType = data.key || extractSensorType(originalTopic);
        if (sensorType && sensorType !== 'unknown') {
            msg.topic = "DaryaMartsinouskaya/feeds/" + sensorType;
            node.log('Normalized object value: ' + sensorType + ' = ' + msg.payload);
            return msg;
        }
    }
    // Если это простой объект (сырой JSON)
    else {
        // Пытаемся извлечь числовое значение
        for (var key in data) {
            if (typeof data[key] === 'number') {
                msg.payload = data[key];

                var sensorType = extractSensorType(originalTopic);
                if (sensorType && sensorType !== 'unknown') {
                    msg.topic = "DaryaMartsinouskaya/feeds/" + sensorType;
                    node.log('Normalized raw object: ' + sensorType + ' = ' + msg.payload);
                    return msg;
                }
                break;
            }
        }
    }
}

// 2. Обработка CSV строк
if (typeof data === 'string' && data.includes(',')) {
    var csvParts = data.split(',');
    var cleanParts = csvParts.filter(function (val) {
        return val !== '' && val !== null && val !== undefined;
    });

    // Если в CSV только одно значение (например "19.2" из "19.2,,,")
    if (cleanParts.length === 1) {
        var val = cleanParts[0].trim();
        var num = parseFloat(val);

        if (!isNaN(num)) {
            msg.payload = num;
        } else {
            msg.payload = val; // Для строковых значений как "DETECTED"
        }

        // Определяем тип сенсора из топика
        var sensorType = extractSensorType(originalTopic);
        if (sensorType && sensorType !== 'unknown') {
            // CSV топики часто содержат данные всех сенсоров
            // Предположим, что это основной CSV фид
            msg.topic = "DaryaMartsinouskaya/feeds/" + sensorType;
            node.log('Normalized CSV: ' + sensorType + ' = ' + msg.payload);
            return msg;
        }
    }
}

// 3. Обработка простых строк и чисел
if (typeof data === 'string' || typeof data === 'number') {
    var value = data;

    // Преобразуем строку в число если возможно
    if (typeof value === 'string') {
        var num = parseFloat(value);
        if (!isNaN(num)) {
            value = num;
        }
    }

    msg.payload = value;

    // Определяем тип сенсора
    var sensorType = extractSensorType(originalTopic);
    if (sensorType && sensorType !== 'unknown') {
        msg.topic = "DaryaMartsinouskaya/feeds/" + sensorType;
        node.log('Normalized simple: ' + sensorType + ' = ' + msg.payload);
        return msg;
    }
}

// 4. Не удалось нормализовать
node.warn('Cannot normalize: topic=' + originalTopic + ', data type=' + typeof data + ', value=' + data);
return null;

// Фильтруем только нужные топики и предотвращаем дублирование
var validTopics = [
    'DaryaMartsinouskaya/feeds/temperature',
    'DaryaMartsinouskaya/feeds/humidity',
    'DaryaMartsinouskaya/feeds/gas',
    'DaryaMartsinouskaya/feeds/motion',
    'DaryaMartsinouskaya/feeds/fan'
];

// Отбрасываем CSV, JSON и другие ненужные топики
if (validTopics.includes(msg.topic)) {
    // Проверяем значение
    if (msg.topic.includes('temperature') && msg.payload === 'DETECTED') {
        node.warn('Invalid temperature value: ' + msg.payload);
        return null;
    }

    if (msg.topic.includes('humidity') && msg.payload === 'DETECTED') {
        node.warn('Invalid humidity value: ' + msg.payload);
        return null;
    }

    // Логируем для отладки
    node.log('Valid topic processed: ' + msg.topic + ' = ' + msg.payload);

    return msg;
}

// Игнорируем CSV, JSON и другие форматы
// Также игнорируем числовые ID топики (3278187 и т.д.)
if (msg.topic.includes('/json') || msg.topic.includes('/csv') || /\d{7}/.test(msg.topic)) {
    node.log('Ignoring duplicate topic format: ' + msg.topic);
    return null;
}

return null;

// Real Data Monitor - с отладкой
var topic = msg.topic || '';
var isTestMessage = msg._test === true ||
    msg._direct_injection === true ||
    msg._scenario === true;

// Логируем все входящие сообщения для отладки
node.log(`Incoming message - Topic: ${topic}, Test: ${isTestMessage}, Payload: ${typeof msg.payload}`);

// Если это реальное MQTT сообщение (не тестовое)
if (!isTestMessage && topic.includes('DaryaMartsinouskaya/feeds/')) {
    // Сохраняем время последних реальных данных
    flow.set('lastRealMqttData', Date.now());

    // Проверяем, включен ли тестовый режим
    var testModeActive = flow.get('testMode') || false;

    node.log(`Real MQTT data detected: ${topic} = ${msg.payload}, Test mode: ${testModeActive}`);

    // Если тестовый режим включен, но получены реальные данные
    // автоматически выключаем тестовый режим
    if (testModeActive) {
        node.log('Real MQTT data detected while in test mode. Auto-switching to normal mode.');

        // Выключаем тестовый режим
        flow.set('testMode', false);

        // Отправляем команду выключения
        return [{
            topic: 'force_test_mode_off',
            payload: false,
            _auto_switch: true,
            reason: 'Real MQTT data detected',
            timestamp: new Date().toISOString()
        }, msg]; // Передаем оригинальное сообщение дальше
    }
} else if (isTestMessage) {
    node.log(`Test message ignored for real data tracking: ${topic}`);
}

// Всегда передаем сообщение дальше
return msg;

// Определяем статус LED для газа
let gasValue = parseFloat(msg.payload);
if (isNaN(gasValue)) gasValue = 0;

msg.payload = gasValue > 1000; // Газ > 1000 = опасность
msg.topic = "gas_led";
return msg;

// Определяем статус LED для температуры
let tempValue = parseFloat(msg.payload);
if (isNaN(tempValue)) tempValue = 0;

// Температура вне диапазона 10-35°C
msg.payload = tempValue < 10 || tempValue > 35;
msg.topic = "temp_led";
return msg;

// Определяем статус LED для влажности
let humidityValue = parseFloat(msg.payload);
if (isNaN(humidityValue)) humidityValue = 0;

// Влажность > 90%
msg.payload = humidityValue > 90;
msg.topic = "humidity_led";
return msg;

msg.topic = "DaryaMartsinouskaya/feeds/fan";
msg.payload = msg.payload ? "ON" : "OFF";
return msg;

// Буферизация последних 12 значений (1 час при 5-минутном интервале)
context.buffer = context.buffer || [];

// Сохраняем данные с меткой времени
var dataPoint = {
    timestamp: new Date().toISOString(),
    sensor: msg.topic,
    value: msg.payload
};

context.buffer.push(dataPoint);

// Держим только последние 12 значений
if (context.buffer.length > 12) {
    context.buffer = context.buffer.slice(-12);
}

// Если буфер полный, отправляем для анализа
if (context.buffer.length === 12) {
    // Создаем объект с последними данными
    var recentData = {
        temperature: 0,
        humidity: 0,
        gas: 0,
        motion: 0
    };

    // Извлекаем последние значения каждого типа
    context.buffer.forEach(function (item) {
        if (item.sensor === 'temperature') recentData.temperature = item.value;
        if (item.sensor === 'humidity') recentData.humidity = item.value;
        if (item.sensor === 'gas') recentData.gas = item.value;
        if (item.sensor === 'motion') recentData.motion = item.value;
    });

    // Отправляем для предиктивного анализа
    node.send({
        topic: "ml_input",
        payload: recentData,
        buffer: context.buffer
    });
}

return null;

// Простая предиктивная модель на основе правил
var data = msg.payload;
var prediction = {
    timestamp: new Date().toISOString(),
    current_gas: data.gas,
    prediction_15min: data.gas,
    prediction_30min: data.gas,
    risk_level: "low",
    recommendation: "normal"
};

// Анализ тренда - обновленные пороги для ppm CO2
// Нормальный уровень: 400-600 ppm
// Повышенный: 600-1000 ppm
// Опасный: >1000 ppm

if (data.gas > 600) {
    // Прогноз на 15 минут (более консервативный)
    prediction.prediction_15min = Math.min(3000, data.gas * (1 + (data.gas - 600) / 1500));

    // Прогноз на 30 минут
    prediction.prediction_30min = Math.min(3500, data.gas * (1 + 2 * (data.gas - 600) / 1500));
} else if (data.gas > 450) {
    // Небольшое повышение
    prediction.prediction_15min = data.gas * 1.05;
    prediction.prediction_30min = data.gas * 1.1;
}

// Учет температуры (высокая температура увеличивает риск)
if (data.temperature > 28) {
    prediction.prediction_15min *= 1.08;
    prediction.prediction_30min *= 1.15;
} else if (data.temperature > 25) {
    prediction.prediction_15min *= 1.03;
    prediction.prediction_30min *= 1.05;
}

// Учет движения (активность = больше CO2)
if (data.motion) {
    prediction.prediction_15min *= 1.02;
    prediction.prediction_30min *= 1.04;
}

// Учет влажности (высокая влажность ухудшает качество воздуха)
if (data.humidity > 80) {
    prediction.prediction_15min *= 1.05;
    prediction.prediction_30min *= 1.08;
}

// Определение уровня риска (скорректированные пороги)
if (prediction.prediction_30min > 1800) {
    prediction.risk_level = "critical";
    prediction.recommendation = "emergency_fan_on";
} else if (prediction.prediction_30min > 1300) {
    prediction.risk_level = "high";
    prediction.recommendation = "preventive_fan_on";
} else if (prediction.prediction_30min > 900) {
    prediction.risk_level = "medium";
    prediction.recommendation = "monitor_closely";
} else if (prediction.prediction_30min > 600) {
    prediction.risk_level = "elevated";
    prediction.recommendation = "ventilate_recommended";
} else {
    prediction.risk_level = "low";
    prediction.recommendation = "normal";
}

// Округляем значения
prediction.prediction_15min = Math.round(prediction.prediction_15min);
prediction.prediction_30min = Math.round(prediction.prediction_30min);

msg.payload = prediction;
msg.topic = "prediction";

return msg;

// Принимаем превентивные меры на основе прогноза
var prediction = msg.payload;
var controlAction = {
    timestamp: new Date().toISOString(),
    action: "none",
    reason: "",
    fan_command: "OFF"
};

// Логика превентивного управления (обновленные пороги)
if (prediction.recommendation === "emergency_fan_on") {
    // Экстренное включение при критическом уровне
    controlAction.action = "emergency_fan_on";
    controlAction.reason = "КРИТИЧЕСКИЙ УРОВЕНЬ! Прогноз через 30 минут: " + prediction.prediction_30min + " ppm";
    controlAction.fan_command = "ON";

    node.send({
        topic: "DaryaMartsinouskaya/feeds/fan",
        payload: "ON",
        control: controlAction
    });
}
else if (prediction.recommendation === "preventive_fan_on") {
    // Превентивное включение при высоком риске
    controlAction.action = "preventive_fan_on";
    controlAction.reason = "Высокий риск. Прогноз через 30 минут: " + prediction.prediction_30min + " ppm (норма <900)";
    controlAction.fan_command = "ON";

    node.send({
        topic: "DaryaMartsinouskaya/feeds/fan",
        payload: "ON",
        control: controlAction
    });
}
else if (prediction.recommendation === "monitor_closely") {
    // Мониторинг без автоматических действий
    controlAction.action = "monitoring";
    controlAction.reason = "Средний риск. Прогноз через 30 минут: " + prediction.prediction_30min + " ppm";
}
else if (prediction.recommendation === "ventilate_recommended") {
    // Рекомендация проветрить (без автоматического включения)
    controlAction.action = "ventilate_recommended";
    controlAction.reason = "Повышенный уровень CO2. Текущий: " + prediction.current_gas + " ppm. Рекомендуется проветривание";
    controlAction.fan_command = "OFF";
}
else if (prediction.recommendation === "normal" && prediction.current_gas < 550) {
    // Если газ в норме и прогноз хороший, выключаем вентилятор
    if (prediction.current_gas < 500) {
        controlAction.action = "fan_off_safe";
        controlAction.reason = "Нормальный уровень газа: " + prediction.current_gas + " ppm. Вентиляция не требуется";
        controlAction.fan_command = "OFF";

        node.send({
            topic: "DaryaMartsinouskaya/feeds/fan",
            payload: "OFF",
            control: controlAction
        });
    }
}

// Для визуализации
msg.payload = controlAction;
msg.topic = "preventive_control";

return msg;

// Конвертируем прогноз в уровень риска 0-100%
var prediction = msg.payload;
var riskLevel = 0;

// Обновленные пороги в соответствии с Predictive Analysis
if (prediction.prediction_30min > 1800) {
    // Критический уровень
    riskLevel = 90 + Math.min(10, (prediction.prediction_30min - 1800) / 20);
} else if (prediction.prediction_30min > 1300) {
    // Высокий уровень
    riskLevel = 70 + Math.min(20, (prediction.prediction_30min - 1300) / 10);
} else if (prediction.prediction_30min > 900) {
    // Средний уровень
    riskLevel = 40 + Math.min(30, (prediction.prediction_30min - 900) / 15);
