// В начале функции, после получения команды:
var command = msg.payload;
var topic = msg.topic || '';
var timestamp = new Date().toISOString();

// Сохраняем время активации тестового режима
if (topic === 'test_mode' && (command === true || command === 'true' || command === 'ON')) {
    flow.set('testModeLastActivation', timestamp);
    node.log('Test mode activated at: ' + timestamp);
}

// Определяем новое состояние
var newTestMode = flow.get('testMode') || false; // По умолчанию текущее значение

// Обрабатываем команды
if (topic === 'force_test_mode_off' || topic === 'reset_test_system') {
    newTestMode = false;
    node.log('Force disabling test mode');
} else if (topic === 'test_mode') {
    // Обрабатываем разные форматы значения
    if (command === true || command === 'true' || command === 'ON' || command === 1 || command === '1') {
        newTestMode = true;
    } else if (command === false || command === 'false' || command === 'OFF' || command === 0 || command === '0') {
        newTestMode = false;
    }
} else if (topic === 'manual_test_mode_toggle') {
    // Инвертируем текущее состояние
    newTestMode = !newTestMode;
}

// Сохраняем состояние ВСЮДУ
flow.set('testMode', newTestMode);
context.set('testMode', newTestMode);
global.set('testMode', newTestMode);

// Логируем
node.log('=== TEST MODE === ' + (newTestMode ? 'ON (real data ignored)' : 'OFF (real data processed)'));

// Статус ноды
node.status({
    fill: newTestMode ? 'green' : 'red',
    shape: 'dot',
    text: 'Test Mode: ' + (newTestMode ? 'ON' : 'OFF')
});

// Создаем сообщение для системы
var systemMsg = {
    topic: 'system_test_mode',
    payload: newTestMode,
    timestamp: timestamp,
    _source: 'central_controller'
};

// Создаем сообщение для UI статуса
var uiStatusMsg = {
    topic: 'test_mode_ui_status',
    payload: {
        test_mode: newTestMode,
        status: newTestMode ? 'TEST MODE' : 'NORMAL MODE',
        message: newTestMode ? 'Real MQTT data is ignored' : 'Processing real data',
        timestamp: timestamp,
        color: newTestMode ? '#ffc107' : '#28a745',
        bg_color: newTestMode ? '#fff3cd' : '#d4edda',
        icon: newTestMode ? '🛠️' : '✅'
    }
};

// Создаем сообщение для синхронизации переключателя
var switchSyncMsg = {
    topic: 'sync_test_mode_switch',
    payload: newTestMode,
    timestamp: timestamp
};

// Возвращаем все сообщения
return [[systemMsg, uiStatusMsg, switchSyncMsg]];

// Распределяет сообщения о тестовом режиме по системе
var messages = msg.payload;
var outputs = [[], [], [], []]; // 4 выхода

if (Array.isArray(messages)) {
    messages.forEach(function(msgItem) {
        switch(msgItem.topic) {
            case 'system_test_mode':
                // 1. Для парсера MQTT
                outputs[0].push({
                    topic: 'mqtt_parser_config',
                    payload: msgItem.payload
                });
                break;

            case 'test_mode_ui_status':
                // 2. Для UI отображения
                outputs[1].push({
                    topic: 'test_mode_display',
                    payload: msgItem.payload
                });
                // 3. Для главной панели
                outputs[2].push({
                    topic: 'system_mode_display',
                    payload: msgItem.payload
                });
                break;

            case 'sync_test_mode_switch':
                // 4. Для синхронизации переключателя
                outputs[3].push({
                    topic: 'test_mode',
                    payload: msgItem.payload
                });
                break;
        }
    });
}

return outputs;

// Автоматически выключает тестовый режим через 2 минуты
// и периодически проверяет соединение с физической платой

// 1. Автоматический сброс через 2 минуты после активации тестового режима
var testModeActive = flow.get('testMode') || false;
var lastActivation = flow.get('testModeLastActivation') || null;

if (testModeActive && lastActivation) {
    var activationTime = new Date(lastActivation);
    var currentTime = new Date();
    var diffMinutes = (currentTime - activationTime) / (1000 * 60);

    if (diffMinutes > 2) { // 2 минуты
        node.log('Auto-reset: Test mode active for more than 2 minutes, switching to normal mode');

        // Выключаем тестовый режим
        flow.set('testMode', false);
        context.set('testMode', false);

        // Отправляем команду выключения
        return [{
            topic: 'force_test_mode_off',
            payload: false,
            _auto_reset: true,
            timestamp: new Date().toISOString()
        }];
    }
}

// 2. Мониторинг физического соединения
// Проверяем, есть ли реальные данные от MQTT
var lastRealData = flow.get('lastRealMqttData') || 0;
var currentTime = Date.now();
var diffSeconds = (currentTime - lastRealData) / 1000;

if (diffSeconds > 30 && !testModeActive) { // Нет данных 30 секунд
    node.warn('No real MQTT data for 30 seconds. Checking connection...');

    // Можно добавить дополнительные проверки соединения
    return [{
        topic: 'connection_status',
        payload: {
            status: 'warning',
            message: 'No real data for 30 seconds',
            timestamp: new Date().toISOString()
        }
    }];
}

return null;

let lastUpdateId = flow.get("last_update_id") || 0;
let updates = msg.payload.result;

if (!updates || !Array.isArray(updates)) return null;

let results = [];

for (let i = 0; i < updates.length; i++) {
    let update = updates[i];
    let updateId = update.update_id;
    let message = update.message;

    if (updateId > lastUpdateId && message && message.text) {
        let text = message.text;
        let chatId = message.chat.id;

        if (updateId > lastUpdateId) lastUpdateId = updateId;

        let command = "";
        if (text === "/status") command = "STATUS";
        else if (text === "/sensors") command = "SENSORS";
        else if (text === "/alerts") command = "ALERTS";
        else if (text === "/help") command = "HELP";
        else if (text === "/fan_on") command = "FAN_ON";
        else if (text === "/fan_off") command = "FAN_OFF";
        else if (text === "/fan_auto") command = "FAN_AUTO";
        else continue;

        if (command !== "") {
            node.log("📤 Command: " + command);

            flow.set("telegram_chat_id", chatId);

            results.push([
                {
                    topic: "DaryaMartsinouskaya/feeds/telegram_commands",
                    payload: command,
                    qos: 1,
                    retain: false
                },
                {
                    payload: {
                        chat_id: chatId,
                        text: "✅ Command received: " + command
                    },
                    url: "https://api.telegram.org/bot[REDACTED_BOT_TOKEN]/sendMessage"
                }
            ]);
        }
    }
}

flow.set("last_update_id", lastUpdateId);

if (results.length === 0) return null;

return [].concat(...results);

let chatId = flow.get("telegram_chat_id") || "[REDACTED_CHAT_ID]";
let responseText = String(msg.payload);

return {
    payload: {
        chat_id: chatId,
        text: responseText,
        parse_mode: "Markdown"
    }
};

let payload = msg.payload;
let message = "";
let chatId = flow.get("telegram_chat_id") || "[REDACTED_CHAT_ID]";

if (typeof payload === 'string') {
    if (payload.startsWith("GAS_ALERT:")) {
