    }
}

if (message === "") return null;

return {
    payload: {
        chat_id: chatId,
        text: message,
        parse_mode: "Markdown"
    }
};

let actualValues = context.actualValues || [];
let predictedValues = context.predictedValues || [];
let currentGas = msg.payload;

if (typeof currentGas === 'string') {
    currentGas = parseFloat(currentGas);
}

if (typeof currentGas === 'number' && currentGas > 0 && !isNaN(currentGas)) {
    actualValues.push({ value: currentGas, timestamp: Date.now() });
    if (actualValues.length > 50) actualValues = actualValues.slice(-50);

    if (actualValues.length > 6) {
        let predicted = actualValues[actualValues.length - 7];
        if (predicted) {
            let newPrediction = {
                actual: currentGas,
                predicted: predicted.value,
                timestamp: Date.now()
            };
            predictedValues.push(newPrediction);
            if (predictedValues.length > 50) predictedValues = predictedValues.slice(-50);

            let sharedPredictions = flow.get("shared_predicted_values") || [];
            sharedPredictions.push(newPrediction);
            if (sharedPredictions.length > 50) sharedPredictions = sharedPredictions.slice(-50);
            flow.set("shared_predicted_values", sharedPredictions);

            node.log("📊 Total predictions: " + sharedPredictions.length);
        }
    }

    context.actualValues = actualValues;
    context.predictedValues = predictedValues;
}

let metrics = {
    timestamp: new Date().toISOString(),
    mae: 0, rmse: 0, mape: 0, accuracy: 0, samples: predictedValues.length
};

if (predictedValues.length >= 3) {
    let sumAbsError = 0, sumSquaredError = 0, sumAbsPercentError = 0;
    for (let i = 0; i < predictedValues.length; i++) {
        let error = predictedValues[i].actual - predictedValues[i].predicted;
        let absError = Math.abs(error);
        sumAbsError += absError;
        sumSquaredError += error * error;
        sumAbsPercentError += (absError / (predictedValues[i].actual + 0.01)) * 100;
    }
    metrics.mae = (sumAbsError / predictedValues.length).toFixed(1);
    metrics.rmse = Math.sqrt(sumSquaredError / predictedValues.length).toFixed(1);
    metrics.mape = (sumAbsPercentError / predictedValues.length).toFixed(1);
    let acc = ((1 - metrics.mae / 500) * 100);
    metrics.accuracy = Math.min(100, Math.max(0, acc)).toFixed(1);
}

return { payload: metrics, topic: "metrics" };

let m = msg.payload;
return [
    { payload: parseFloat(m.mae), topic: "mae" },
    { payload: parseFloat(m.rmse), topic: "rmse" },
    { payload: parseFloat(m.mape), topic: "mape" },
    { payload: parseFloat(m.accuracy), topic: "accuracy" },
    { payload: m, topic: "summary" }
];

let predictedValues = flow.get("shared_predicted_values") || [];

if (predictedValues.length === 0) {
    return null;
}

// Берём последнюю ошибку
let last = predictedValues[predictedValues.length - 1];

let error = Math.abs(last.actual - last.predicted);

msg.payload = error;
msg.topic = "Prediction Error";

return msg;

context.actualValues = [];
context.predictedValues = [];
flow.set("shared_predicted_values", []);
flow.set("validation_metrics", null);
node.log("🔄 All cleared");
return null;

// Пропускаем одинаковые значения газа раз в 30 секунд
// чтобы model validation продолжал получать данные

let lastGas = context.get('lastGas') || null;
let lastSentTime = context.get('lastSentTime') || 0;

let gas = msg.payload;

if (typeof gas === 'string') {
    gas = parseFloat(gas);
}

if (isNaN(gas)) {
    return null;
}

let now = Date.now();

// Отправляем если:
// 1. значение изменилось
// ИЛИ
// 2. прошло 30 секунд

if (gas !== lastGas || (now - lastSentTime) > 30000) {
    context.set('lastGas', gas);
    context.set('lastSentTime', now);

    msg.payload = gas;
    return msg;
}

return null;
